using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class RecoveredChargeSceneImporter {
 [Serializable]class ThemeBase{public Vector4 bright,dark;}
 [Serializable]class Key {public float time,value,inTangent,outTangent,inWeight,outWeight;public int weightedMode;}
 [Serializable]class Curve {public Key[] keys;public int preWrapMode,postWrapMode;public float period;}
 [Serializable]class Texture:S07RecoveryImporter.TextureRef{public string hdrBytes;public int width,height;}
 [Serializable]class Blueprint{public S07RecoveryImporter.MaterialRef[] materials;public Texture[] textures;}
 const string Src="Assets/Recovery/ExtraScene/Charge/",Dst="Assets/RecoveredS07/Environment/";
 public static RecoveredChargeControls Import(RecoveredLighting lighting){
  var b=JsonUtility.FromJson<Blueprint>(File.ReadAllText(Src+"blueprint.json"));var tex=new Dictionary<string,Texture2D>();foreach(var t in b.textures){if(!string.IsNullOrEmpty(t.hdrBytes)){var image=new Texture2D(t.width,t.height,TextureFormat.RGBAHalf,false,true){name=t.name,filterMode=(FilterMode)t.filterMode,wrapModeU=(TextureWrapMode)t.wrapU,wrapModeV=(TextureWrapMode)t.wrapV};image.LoadRawTextureData(File.ReadAllBytes(t.hdrBytes));image.Apply(false,false);Save(image,Dst+"ChargeHDR_"+t.id+".asset");tex[t.id]=image;continue;}var i=(TextureImporter)AssetImporter.GetAtPath(t.file);i.sRGBTexture=t.colorSpace==1;i.filterMode=(FilterMode)t.filterMode;i.wrapModeU=(TextureWrapMode)t.wrapU;i.wrapModeV=(TextureWrapMode)t.wrapV;i.textureCompression=TextureImporterCompression.Uncompressed;i.SaveAndReimport();tex[t.id]=AssetDatabase.LoadAssetAtPath<Texture2D>(t.file);}
  var mats=new Dictionary<string,Material>();foreach(var entry in b.materials){var shader=Shader.Find("Recovered/Hidden/BG_Charge/Variant1");if(shader==null||ShaderUtil.ShaderHasError(shader))throw new InvalidOperationException("Native charging background shader failed");var mat=new Material(shader){name=entry.name,renderQueue=entry.renderQueue};foreach(var c in entry.colors)if(mat.HasProperty(c.name))mat.SetColor(c.name,c.value);foreach(var f in entry.floats)if(mat.HasProperty(f.name))mat.SetFloat(f.name,f.value);foreach(var t in entry.textures){mat.SetTexture(t.name,tex[t.texture]);mat.SetTextureScale(t.name,t.scale);mat.SetTextureOffset(t.name,t.offset);}Save(mat,Dst+"ChargeBackground_"+entry.id+".mat");mats[entry.id]=mat;}
  var go=new GameObject("NativeChargeScene");go.AddComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Dst+"ExtraSceneFloorAndSky.asset");var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=mats["5"];var ctrl=go.AddComponent<RecoveredChargeControls>();ctrl.brightMaterial=mats["5"];ctrl.darkMaterial=mats["6"];ctrl.directDark=JsonUtility.FromJson<ThemeBase>(File.ReadAllText(Src+"theme-base.json")).dark;ctrl.background=r;ctrl.lighting=lighting;var data=JsonUtility.FromJson<Curve>(File.ReadAllText(Src+"curve.json"));ctrl.curve=new AnimationCurve(Array.ConvertAll(data.keys,k=>new Keyframe(k.time,k.value,k.inTangent,k.outTangent,k.inWeight,k.outWeight){weightedMode=(WeightedMode)k.weightedMode})){preWrapMode=(WrapMode)data.preWrapMode,postWrapMode=(WrapMode)data.postWrapMode};ctrl.period=data.period;ctrl.SetVisible(false);return ctrl;
 }
 static void Save(UnityEngine.Object obj,string path){AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(obj,path);}
}
